                outside.add((nr, nc))
                stack.append((nr, nc))

    out = [row[:] for row in grid]
    remaining = {(r, c) for r in range(h) for c in range(w)
                 if grid[r][c] == 0 and (r, c) not in outside}

    while remaining:
        start = remaining.pop()
        comp = {start}
        stack = [start]
        while stack:
            r, c = stack.pop()
            for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
